from django.utils import timezone

ACTIVAS = ['abierta', 'reconocida']


def resolver_duplicadas(apps, schema_editor):
    """Antes de la restricción, deja UNA alerta activa por (regla, estación): la más vieja,
    que es la que se notificó primero. Las demás son el mismo problema abierto dos veces
    (CR-2) y se marcan resueltas, con su historial intacto. Si no hay duplicadas, no hace
    nada. Sin esto, crear el índice único fallaría en una base que ya las tiene."""
    Alerta = apps.get_model('monitoreo', 'Alerta')
    grupos = (
        Alerta.objects.filter(estado__in=ACTIVAS).values('regla_id', 'estacion_id')
        .annotate(total=Count('id'), primera=Min('id')).filter(total__gt=1)
    )
    ahora = timezone.now()
    for grupo in grupos:
        Alerta.objects.filter(
            regla_id=grupo['regla_id'], estacion_id=grupo['estacion_id'], estado__in=ACTIVAS,
        ).exclude(id=grupo['primera']).update(estado='resuelta', resuelta_en=ahora)


